import json

def rotate_90_clockwise(grid):
    """Rotate grid 90 degrees clockwise."""
    n = len(grid)
    m = len(grid[0])
    # New grid has dimensions m x n
    result = [[0] * n for _ in range(m)]
    for i in range(n):
        for j in range(m):
            result[m - 1 - j][i] = grid[i][j]
    return result

def rotate_90_counter_clockwise(grid):
    """Rotate grid 90 degrees counter-clockwise."""
    n = len(grid)
    m = len(grid[0])
    result = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            result[n - 1 - j][i] = grid[i][j]
    return result

def rotate_180(grid):
    """Rotate grid 180 degrees."""
    return rotate_90_clockwise(rotate_90_clockwise(grid))

